CREATE TABLE projects (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 300), description TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL CHECK(active IN (0,1))) STRICT;
ALTER TABLE document_lines ADD COLUMN project_id TEXT REFERENCES projects(id);
ALTER TABLE document_lines ADD COLUMN project_name TEXT NOT NULL DEFAULT '';
CREATE INDEX lines_project ON document_lines(project_id,account_id);
CREATE TRIGGER audit_capture_projects_insert AFTER INSERT ON projects WHEN EXISTS(SELECT 1 FROM audit_context) BEGIN INSERT INTO audit_changes(audit_id,table_name,row_key,before_state,after_state) SELECT audit_id,'projects',json_array(CAST(NEW.id AS TEXT)),NULL,json_object('id',CAST(NEW.id AS TEXT),'code',CAST(NEW.code AS TEXT),'name',CAST(NEW.name AS TEXT),'description',CAST(NEW.description AS TEXT),'active',CAST(NEW.active AS TEXT)) FROM audit_context WHERE id=1 ON CONFLICT(audit_id,table_name,row_key) DO UPDATE SET after_state=excluded.after_state; END;
CREATE TRIGGER audit_capture_projects_update AFTER UPDATE ON projects WHEN EXISTS(SELECT 1 FROM audit_context) AND json_object('id',CAST(OLD.id AS TEXT),'code',CAST(OLD.code AS TEXT),'name',CAST(OLD.name AS TEXT),'description',CAST(OLD.description AS TEXT),'active',CAST(OLD.active AS TEXT)) IS NOT json_object('id',CAST(NEW.id AS TEXT),'code',CAST(NEW.code AS TEXT),'name',CAST(NEW.name AS TEXT),'description',CAST(NEW.description AS TEXT),'active',CAST(NEW.active AS TEXT)) BEGIN INSERT INTO audit_changes(audit_id,table_name,row_key,before_state,after_state) SELECT audit_id,'projects',json_array(CAST(NEW.id AS TEXT)),json_object('id',CAST(OLD.id AS TEXT),'code',CAST(OLD.code AS TEXT),'name',CAST(OLD.name AS TEXT),'description',CAST(OLD.description AS TEXT),'active',CAST(OLD.active AS TEXT)),json_object('id',CAST(NEW.id AS TEXT),'code',CAST(NEW.code AS TEXT),'name',CAST(NEW.name AS TEXT),'description',CAST(NEW.description AS TEXT),'active',CAST(NEW.active AS TEXT)) FROM audit_context WHERE id=1 ON CONFLICT(audit_id,table_name,row_key) DO UPDATE SET after_state=excluded.after_state; END;
CREATE TRIGGER audit_capture_projects_delete AFTER DELETE ON projects WHEN EXISTS(SELECT 1 FROM audit_context) BEGIN INSERT INTO audit_changes(audit_id,table_name,row_key,before_state,after_state) SELECT audit_id,'projects',json_array(CAST(OLD.id AS TEXT)),json_object('id',CAST(OLD.id AS TEXT),'code',CAST(OLD.code AS TEXT),'name',CAST(OLD.name AS TEXT),'description',CAST(OLD.description AS TEXT),'active',CAST(OLD.active AS TEXT)),NULL FROM audit_context WHERE id=1 ON CONFLICT(audit_id,table_name,row_key) DO UPDATE SET after_state=excluded.after_state; END;
DROP TRIGGER audit_capture_document_lines_insert;
DROP TRIGGER audit_capture_document_lines_update;
DROP TRIGGER audit_capture_document_lines_delete;
CREATE TRIGGER audit_capture_document_lines_insert AFTER INSERT ON document_lines WHEN EXISTS(SELECT 1 FROM audit_context) BEGIN INSERT INTO audit_changes(audit_id,table_name,row_key,before_state,after_state) SELECT audit_id,'document_lines',json_array(CAST(NEW.document_id AS TEXT),CAST(NEW.position AS TEXT)),NULL,json_object('document_id',CAST(NEW.document_id AS TEXT),'position',CAST(NEW.position AS TEXT),'account_id',CAST(NEW.account_id AS TEXT),'partner_id',CAST(NEW.partner_id AS TEXT),'partner_name',CAST(NEW.partner_name AS TEXT),'account_name',CAST(NEW.account_name AS TEXT),'description',CAST(NEW.description AS TEXT),'debit',CAST(NEW.debit AS TEXT),'credit',CAST(NEW.credit AS TEXT),'project_id',CAST(NEW.project_id AS TEXT),'project_name',CAST(NEW.project_name AS TEXT)) FROM audit_context WHERE id=1 ON CONFLICT(audit_id,table_name,row_key) DO UPDATE SET after_state=excluded.after_state; END;
