description',CAST(NEW.description AS TEXT),'debit',CAST(NEW.debit AS TEXT),'credit',CAST(NEW.credit AS TEXT),'project_id',CAST(NEW.project_id AS TEXT),'project_name',CAST(NEW.project_name AS TEXT)) FROM audit_context WHERE id=1 ON CONFLICT(audit_id,table_name,row_key) DO UPDATE SET after_state=excluded.after_state; END;
CREATE TRIGGER audit_capture_document_lines_delete AFTER DELETE ON document_lines WHEN EXISTS(SELECT 1 FROM audit_context) BEGIN INSERT INTO audit_changes(audit_id,table_name,row_key,before_state,after_state) SELECT audit_id,'document_lines',json_array(CAST(OLD.document_id AS TEXT),CAST(OLD.position AS TEXT)),json_object('document_id',CAST(OLD.document_id AS TEXT),'position',CAST(OLD.position AS TEXT),'account_id',CAST(OLD.account_id AS TEXT),'partner_id',CAST(OLD.partner_id AS TEXT),'partner_name',CAST(OLD.partner_name AS TEXT),'account_name',CAST(OLD.account_name AS TEXT),'description',CAST(OLD.description AS TEXT),'debit',CAST(OLD.debit AS TEXT),'credit',CAST(OLD.credit AS TEXT),'project_id',CAST(OLD.project_id AS TEXT),'project_name',CAST(OLD.project_name AS TEXT)),NULL FROM audit_context WHERE id=1 ON CONFLICT(audit_id,table_name,row_key) DO UPDATE SET after_state=excluded.after_state; END;
